import hmac
import hashlib
import time
import os
from flask import Flask, request, jsonify, abort
from functools import wraps
import sqlite3
import secrets

app = Flask(__name__)
SECRET_KEY = os.environ.get('HMAC_SECRET', secrets.token_hex(32))
NONCE_EXPIRY = 300  # 5 minutes
MAX_CLOCK_SKEW = 30  # seconds

def get_db():
    db = sqlite3.connect('/tmp/nonces.db')
    db.execute('CREATE TABLE IF NOT EXISTS used_nonces (nonce TEXT PRIMARY KEY, timestamp REAL, client_ip TEXT)')
    return db

def cleanup_expired_nonces(db):
    cutoff = time.time() - NONCE_EXPIRY
    db.execute('DELETE FROM used_nonces WHERE timestamp < ?', (cutoff,))
    db.commit()

def compute_signature(method, path, timestamp, nonce, body_hash, client_ip):
    """Compute HMAC signature over request components."""
    # Include client IP to bind signature to originating host
    message = f"{method}\n{path}\n{timestamp}\n{nonce}\n{body_hash}\n{client_ip}"
    return hmac.new(SECRET_KEY.encode(), message.encode(), hashlib.sha256).hexdigest()

def get_client_ip():
    """Extract client IP, respecting reverse proxy headers."""
    # Trust X-Real-IP set by our nginx reverse proxy (single trusted hop)
    real_ip = request.headers.get('X-Real-IP', '')
    if real_ip:
        return real_ip.strip()
    return request.remote_addr

def verify_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        sig = request.headers.get('X-Signature')
        timestamp_str = request.headers.get('X-Timestamp')
        nonce = request.headers.get('X-Nonce')

        if not all([sig, timestamp_str, nonce]):
            abort(401, description='Missing authentication headers')

        try:
            timestamp = float(timestamp_str)
        except (ValueError, TypeError):
            abort(401, description='Invalid timestamp')

        # Check timestamp freshness
        now = time.time()
        if abs(now - timestamp) > MAX_CLOCK_SKEW:
            abort(401, description='Request timestamp too old or too far in future')

        db = get_db()
        try:
            cleanup_expired_nonces(db)

            # Compute expected signature
            body_hash = hashlib.sha256(request.get_data()).hexdigest()
            client_ip = get_client_ip()

            expected_sig = compute_signature(
                request.method, request.path, timestamp, nonce, body_hash, client_ip
            )

            if not hmac.compare_digest(sig, expected_sig):
                abort(401, description='Invalid signature')

            # Atomically record the nonce as used. Relying on the PRIMARY KEY
            # constraint prevents the TOCTOU race present in a separate
            # SELECT-then-INSERT flow: a duplicate nonce insertion fails
            # atomically, so concurrent replays are rejected.
            try:
                db.execute(
                    'INSERT INTO used_nonces (nonce, timestamp, client_ip) VALUES (?, ?, ?)',
                    (nonce, timestamp, client_ip)
                )
                db.commit()
            except sqlite3.IntegrityError:
                db.rollback()
                abort(401, description='Nonce already used')
        finally:
            db.close()

        return f(*args, **kwargs)
    return decorated

@app.route('/api/transfer', methods=['POST'])
@verify_signature
def transfer():
    data = request.get_json()
    if not data:
        abort(400, description='Invalid JSON body')

    from_account = data.get('from')
    to_account = data.get('to')
    amount = data.get('amount')

    if not all([from_account, to_account, amount]):
        abort(400, description='Missing required fields')

    # Process transfer (simplified)
    return jsonify({'status': 'success', 'transfer_id': secrets.token_hex(16)})

@app.route('/api/balance', methods=['GET'])
@verify_signature
def balance():
    account = request.args.get('account')
    if not account:
        abort(400, description='Missing account parameter')
    return jsonify({'account': account, 'balance': 10000.00})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
